begin;
create extension if not exists pgtap with schema extensions;
select plan(23);
-- The backfill names the company's original first stage as Ideas, whatever the stages' order is when it runs.
-- Rewind this company to before the migration (Ideas moved last, Review put first), then run the migration's statement.
alter table public.work_stages disable trigger work_stage_kind_guard;
drop index public.work_stages_one_ideas;
update public.work_stages set kind='before_review' where kind='ideas';
update public.work_stages set position=100 where company_id='10000000-0000-0000-0000-000000000001' and id=(select min(id) from public.work_stages where company_id='10000000-0000-0000-0000-000000000001');
update public.work_stages set position=0 where company_id='10000000-0000-0000-0000-000000000001' and kind='review' and position=(select min(position) from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='review');
update public.work_stages s set kind='ideas' where s.kind='before_review' and s.id=(select min(x.id) from public.work_stages x where x.company_id=s.company_id);
create unique index work_stages_one_ideas on public.work_stages(company_id) where kind='ideas';
alter table public.work_stages enable trigger work_stage_kind_guard;
select is((select count(*)::int from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='ideas' and id=(select min(id) from public.work_stages where company_id='10000000-0000-0000-0000-000000000001')),1,'the original first stage is Ideas even when it was moved last');
select is((select count(*)::int from public.work_stages where company_id='10000000-0000-0000-0000-000000000001' and kind='ideas'),1,'a stage put first by position does not become a second Ideas stage');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select lives_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-1','fp-req-1','create',null,jsonb_build_object('message','Write a post about the new course','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,'a manager sends a message to the account manager');
select lives_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-1','fp-req-1','create',null,jsonb_build_object('message','Write a post about the new course','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,'the same key again is accepted');
select is((select count(*)::int from public.work_cards where title='Write a post about the new course'),1,'the same key creates one card');
select is((select mode from public.work_cards where title='Write a post about the new course'),'plan','the mode is stored');
select is((select count(*)::int from public.work_cards c join public.work_stages s on s.company_id=c.company_id and s.id=c.stage_id where c.title='Write a post about the new course' and s.kind='ideas'),1,'the card is in the Ideas stage');
select is((select count(*)::int from public.work_assignees a join public.work_cards c on c.id=a.card_id where c.title='Write a post about the new course' and a.person_id='30000000-0000-0000-0000-000000000005'),1,'the account manager is assigned');
select is((select count(*)::int from public.work_comments m join public.work_cards c on c.id=m.card_id where c.title='Write a post about the new course' and m.body='Write a post about the new course' and m.author_id='20000000-0000-0000-0000-000000000002'),1,'the first message is on the card, written by the sender');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-1','fp-different','create',null,jsonb_build_object('message','A different message','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,null,'idempotency key reused','the same key with a different message is refused');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-2','fp-req-2','create',null,jsonb_build_object('message','Hello','agent','30000000-0000-0000-0000-000000000004','mode','plan'))$$,null,'agent not found','a member without an agent role cannot be asked');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-3','fp-req-3','create',null,jsonb_build_object('message','Hello','agent','30000000-0000-0000-0000-000000000005','mode','whatever'))$$,'22023',null,'an unknown mode is refused');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-4','fp-req-4','create',null,jsonb_build_object('message','   ','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,'22023',null,'an empty message is refused');
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000002','req-5','fp-req-5','create',null,jsonb_build_object('message','Hello','agent','30000000-0000-0000-0000-000000000005','mode','answer'))$$,null,null,'a person outside the company cannot create a card there');
select set_config('request.jwt.claims',json_build_object('sub','20000000-0000-0000-0000-000000000002','role','authenticated','run_card',1)::text,true);
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-8','fp-req-8','create',null,jsonb_build_object('message','From a run key','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,'P0001','not permitted','a run key cannot start a new card');
select set_config('request.jwt.claims','{}',true);
update public.work_stages set position=100 where company_id='10000000-0000-0000-0000-000000000001' and kind='ideas';
select lives_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-7','fp-req-7','create',null,jsonb_build_object('message','Sent after Ideas was moved','agent','30000000-0000-0000-0000-000000000005','mode','do'))$$,'a request is accepted after the stages were reordered');
select is((select s.kind from public.work_cards c join public.work_stages s on s.company_id=c.company_id and s.id=c.stage_id where c.title='Sent after Ideas was moved'),'ideas','the request still enters Ideas');
-- Eligibility follows the stable agent identity and its grant, not the role key on the membership.
select is((select count(*)::int from public.company_agents('10000000-0000-0000-0000-000000000001') where granted),4,'a member of the company sees its four granted role agents');
reset role;
select set_config('request.jwt.claim.sub','',true);
update public.members set agent_role=null where company_id='10000000-0000-0000-0000-000000000001' and person_id='30000000-0000-0000-0000-000000000005';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select lives_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-9','fp-req-9','create',null,jsonb_build_object('message','Sent after the role key was cleared','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,'an agent whose role key was cleared can still be asked while its grant is active');
reset role;
select set_config('request.jwt.claim.sub','',true);
update public.members set agent_role='account_manager' where company_id='10000000-0000-0000-0000-000000000001' and person_id='30000000-0000-0000-0000-000000000004';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-10','fp-req-10','create',null,jsonb_build_object('message','Hello','agent','30000000-0000-0000-0000-000000000004','mode','plan'))$$,null,'agent not found','a person who took over a role key is not an agent');
reset role;
select set_config('request.jwt.claim.sub','',true);
update public.agent_grants set revoked_at=now(),revoked_by='20000000-0000-0000-0000-000000000001' where company_id='10000000-0000-0000-0000-000000000001' and agent_id='30000000-0000-0000-0000-000000000005';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-11','fp-req-11','create',null,jsonb_build_object('message','Hello','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,null,'agent not found','an agent whose grant was revoked cannot be asked');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select throws_ok($$select public.agent_write('10000000-0000-0000-0000-000000000001','req-6','fp-req-6','create',null,jsonb_build_object('message','Hello','agent','30000000-0000-0000-0000-000000000005','mode','plan'))$$,null,'not permitted','a viewer cannot send a card request');
select is((select count(*)::int from public.work_cards where title='Hello'),0,'refused requests create no card');
select * from finish();
rollback;
